corrected_code:
const { createYoga, createSchema } = require('graphql-yoga');
const { createServer } = require('node:http');
const { GraphQLError } = require('graphql');

const consignmentsDb = new Map();

const typeDefs = `
  type FreightConsignment @key(fields: "trackingRef") {
    trackingRef: ID!
    totalWeightKg: Float!
    palletCount: Int!
    destinationHub: String!
    transitStatus: String!
  }

  type Query {
    healthCheck: Boolean
  }
`;

const resolvers = {
  FreightConsignment: {
    __resolveReference: (ref, context) => {
      if (!context.shipperAccountId) {
        throw new GraphQLError('Shipper account credentials required', {
          extensions: { code: 'UNAUTHENTICATED' }
        });
      }

      const consignment = consignmentsDb.get(ref.trackingRef);
      if (!consignment) {
        throw new GraphQLError('Consignment not found', {
          extensions: { code: 'NOT_FOUND' }
        });
      }

      if (consignment.shipperAccountId !== context.shipperAccountId) {
        throw new GraphQLError('Access denied to foreign consignment data', {
          extensions: { code: 'FORBIDDEN' }
        });
      }

      return consignment;
    }
  }
};

const yoga = createYoga({
  schema: createSchema({ typeDefs, resolvers }),
  context: ({ req }) => ({
    shipperAccountId: req.headers['x-shipper-account']
  })
});

createServer(yoga).listen(4090);
